-- SmartAI of every vanilla dungeon creature the Heroic/Mythic restoration touches, written as complete blocks.
-- Rows from id 9000 are the Ascension boss kits (timers from the Ascension combat logs where a spell shows up there,
-- otherwise from the spell data; checked ingame on Heroic and Mythic). Vanilla rows outside the kit are kept for
-- Normal or switched off with event flag 0x10 (never in 5-man dungeons) so they can be restored.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (3653, 10813, 13738, 17830) AND `ScriptName` = '';
